function migrateVariantInventory(){
  const ps=getRawProducts();
  let changed=false;
  const out=[];
  const btColors=[{color:'verde',flavor:'Menta'},{color:'negro',flavor:'Menta fuerte'},{color:'rojo',flavor:'Sandía'},{color:'aqua',flavor:'Aqua azul'},{color:'celeste',flavor:'Refrescante'},{color:'rosado',flavor:'Bubble Gum'}];
  const buColors=[{color:'negro',flavor:'Menta fuerte'},{color:'azul',flavor:'Aqua azul'},{color:'rojo',flavor:'Sandía'},{color:'verde',flavor:'Menta'}];
  const alColors=['rosado','azul','verde'];
  const laColors=['verde','naranja'];
  const tabacoSabores=['Chocolate','Cherry','Caramelo','Vainilla','Original','Mango','Uva','Arándano','Menta','Sandía','Maracuyá','Coco','Virginia','Café turco','Chicle'];

  // If old Tabaco was a single product, split its stock into the 15 independent flavors.
  ps.forEach(p=>{
    const n=norm(p.name);
    if(n.includes('tabaco bristol') && !p.flavor){
      tabacoSabores.forEach((flavor,i)=>out.push({...p,id:i===0?p.id:uid(),name:'Tabaco Bristol 45 gr · '+flavor,flavor,variantKey:'tabaco-bristol',stock:i===4?Number(p.stock||0):0}));
      changed=true;
    }else out.push(p);
  });

  // Ensure all BigTime/Ultra/Alka 2/Languetazo variants exist even when an older localStorage
  // version had only one generic product. Existing stock stays on the first available variant.
  const ensureGroup=(match,defs,variantKey)=>{
    const rows=out.filter(p=>match(norm(p.name)) && p.variantKey!==variantKey);
    const existing=out.filter(p=>p.variantKey===variantKey);
    if(existing.length>=defs.length)return;
    const base=rows[0]||existing[0];
    if(!base)return;
    if(rows.length){
      const ix=out.indexOf(base);
      out.splice(ix,1);
    }
    const stock=Number(base.stock||0);
    const pricePurchase=Number(base.pricePurchase??base.purchasePrice)||0;
    const price=Number(base.price??base.priceSale)||0;
    const category=base.category;
    defs.forEach((d,i)=>{
      const ex=existing[i];
      if(ex){ out.push(ex); return; }
      out.push({...base,id:i===0?base.id:uid(),name:(variantKey==='bigtime'?'Big Time · ':variantKey==='bigtime-ultra'?'Big Time Ultra · ':variantKey==='alka2'?'Alka 2 · ':'Languetazo · ')+d.flavor,flavor:d.flavor,color:d.color,variantKey,category,pricePurchase,price,stock:i===0?stock:0});
    });
    changed=true;
  };
  ensureGroup(n=>/^bigtime\b/.test(n)&&!n.includes('ultra')&&n!=='bigtime',btColors,'bigtime');
  ensureGroup(n=>n.includes('bigtime ultra')&&!/promo|11200/.test(n),buColors,'bigtime-ultra');
  ensureGroup(n=>n.includes('alka 2'),alColors,'alka2');
  ensureGroup(n=>n.includes('languetaz'),laColors,'languetazo');

  if(changed){writeArray('zipperProductos',out);return true}
  return false;
}

function loadSeed(){return fetch('./data/zipper-seed.json',{cache:'no-store'}).then(r=>r.json()).then(s=>{if(!s||!Array.isArray(s.clients)||!Array.isArray(s.products))return;const ver=String(s.version||'1');if(localStorage.getItem('zipperSeedVersion')===ver)return;const cs=getClients(),ps=getRawProducts();s.clients.forEach(x=>{const name=String(x.name||'').trim();if(name&&!cs.some(c=>norm(c.name)===norm(name)&&norm(c.address)===norm(x.address))){cs.push({...x,id:uid(),route:x.route||'',routeWeek:x.routeWeek||'A',routeDay:x.routeDay||'',active:x.active!==false})}});s.products.forEach(x=>{const name=String(x.name||'').trim();if(name&&!ps.some(p=>norm(p.name)===norm(name)&&Number(p.price)===Number(x.price))){ps.push({...x,id:uid(),name,stock:Number(x.stock)||0,promotions:Array.isArray(x.promotions)?x.promotions:defaultPromos(name)})}});writeArray('zipperClientes',cs);writeArray('zipperProductos',ps);writeArray('zipperCategorias',[...(s.categories||[]),...getCategories()]);localStorage.setItem('zipperSeedVersion',ver);renderHome();renderInventory();renderClients()}).catch(()=>{})}

function latestSalesForClient(id){return getSales().filter(s=>String(s.clienteId)===String(id)).sort((a,b)=>String(b.fecha||'').localeCompare(String(a.fecha||''))||Number(b.folio||0)-Number(a.folio||0))}function renderVisitedSales(id){const rows=latestSalesForClient(id);$('visitedSales').innerHTML=rows.length?'<div class="kicker">VENTAS REGISTRADAS DE ESTE CLIENTE</div>'+rows.map(s=>'<article class="history-row"><div><strong>#'+esc(s.folio)+' · '+esc(s.fecha)+'</strong><span>'+(s.items||[]).map(i=>esc(i.qty)+' × '+esc(i.desc)).join(' · ')+'</span></div><div class="actions-small"><strong>'+money(saleTotal(s))+'</strong><button class="secondary reprint-visited" data-id="'+esc(s.id)+'" type="button">Reimprimir</button></div></article>').join(''):'<p class="muted">Este cliente aún no tiene ventas registradas.</p>';document.querySelectorAll('.reprint-visited').forEach(b=>b.onclick=()=>{const sale=getSales().find(x=>String(x.id)===String(b.dataset.id));if(sale){renderPrint(sale);window.print()}})}function renderHome(){const all=getClients().filter(c=>c.active!==false);const session=routeSession();const setup=$('routeSetup'),activeBox=$('activeRouteBox');if(setup)setup.classList.toggle('hidden',!!session);if($('exceptionSearch'))$('exceptionSearch').classList.toggle('hidden',!exceptionSearch);if(activeBox)activeBox.classList.toggle('hidden',!session||!!selectedClientId);if(session){$('activeRouteLabel').textContent='Semana '+session.week+' · '+session.day;const visited=visitedIds().map(String);let routeClients=all.filter(c=>String(c.routeWeek||'A')===String(session.week)&&norm(c.routeDay)===norm(session.day));if(!exceptionSearch){const hn=norm($('homeName').value),ha=norm($('homeAddress').value);routeClients=routeClients.filter(c=>(!hn||norm(c.name).includes(hn))&&(!ha||norm(c.address).includes(ha)))}if(exceptionSearch){const w=$('otherWeek').value,d=$('otherDay').value,n=norm($('otherName').value),ad=norm($('otherAddress').value);routeClients=all.filter(c=>(!w||String(c.routeWeek)===String(w))&&(!d||norm(c.routeDay)===norm(d))&&(!n||norm(c.name).includes(n))&&(!ad||norm(c.address).includes(ad)));$('otherResults').innerHTML=routeClients.length?routeClients.map(c=>'<article class="route-client"><div><strong>'+esc(c.name)+'</strong><span>'+esc(c.address||'Sin dirección')+'</span><span>Semana '+esc(c.routeWeek||'—')+' · '+esc(c.routeDay||'Sin día')+'</span></div><button class="primary select-client" data-id="'+esc(c.id)+'" type="button">Abrir cliente</button></article>').join(''):'<p class="muted">No hay clientes con esa búsqueda.</p>';}else{const pending=routeClients.filter(c=>!visited.includes(String(c.id)));const rows=showVisited?routeClients.filter(c=>visited.includes(String(c.id))):pending;$('routeClients').innerHTML=rows.length?rows.map(c=>'<article class="route-client '+(showVisited?'visited-row':'')+'"><div><strong>'+esc(c.name)+'</strong><span>'+esc(c.address||'Sin dirección')+'</span><span>Semana '+esc(c.routeWeek||'—')+' · '+esc(c.routeDay||'Sin día')+'</span></div><div class="actions-small">'+(showVisited?'<span class="visited-badge">✓ VISITADO</span><button class="secondary reprint-last" data-id="'+esc(c.id)+'" type="button">Reimprimir último</button><button class="ghost view-client-sales" data-id="'+esc(c.id)+'" type="button">Ventas anteriores</button>':'<button class="primary select-client" data-id="'+esc(c.id)+'" type="button">Abrir cliente</button>')+'</div></article>').join(''):'<p class="muted">'+(showVisited?'Aún no hay clientes visitados.':'No quedan clientes pendientes para esta ruta.')+'</p>';}}else{$('routeClients').innerHTML='';}if(showVisited){$('visitedSales').classList.remove('hidden');$('visitedBack').classList.remove('hidden');document.querySelectorAll('.reprint-last').forEach(b=>b.onclick=()=>{const s=latestSalesForClient(b.dataset.id)[0];if(s){renderPrint(s);window.print()}});document.querySelectorAll('.view-client-sales').forEach(b=>b.onclick=()=>{renderVisitedSales(b.dataset.id);$('visitedSales').scrollIntoView({behavior:'smooth',block:'start'})})}else{$('visitedSales').classList.add('hidden');$('visitedBack').classList.add('hidden')}document.querySelectorAll('.select-client').forEach(b=>b.onclick=()=>openClientCart(b.dataset.id));if($('visitedButton'))$('visitedButton').textContent='Visitados ('+visitedIds().length+')';if(selectedClientId)renderCart()}
function openClientCart(id){const c=clientById(id);if(!c)return;selectedClientId=c.id;cart=[];draftProductId='';draftQty='';showCartTray=false;$('cartClientName').textContent=c.name;$('cartClientMeta').textContent=(c.address||'Sin dirección')+' · Semana '+(c.routeWeek||'—')+' · '+(c.routeDay||'Sin día');$('cartSection').classList.remove('hidden');$('cartSearchName').value='';$('cartCategory').value='';renderHome();renderCart();setTimeout(()=>$('cartSection').scrollIntoView({behavior:'smooth',block:'start'}),50)}
function cartProductMatches(p){const q=norm($('cartSearchName').value),cat=$('cartCategory').value;return(!cat||p.category===cat)&&(!q||norm(p.name).includes(q)||norm(p.color||'').includes(q))}
function renderCart(){if(!selectedClientId)return;const selectedCat=$('cartCategory').value;const active=getProducts().filter(p=>p.active);const cats=[...new Set(active.map(p=>p.category))];$('cartCategory').innerHTML='<option value="">Todas las categorías</option>'+cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');$('cartCategory').value=selectedCat;const q=norm($('cartSearchName').value);const suggestions=q?active.filter(p=>(!selectedCat||p.category===selectedCat)&&(norm(p.name).includes(q)||norm(p.color||'').includes(q))).slice(0,10):[];$('productSuggestions').innerHTML=suggestions.map(p=>'<button type="button" class="suggestion" data-id="'+esc(p.id)+'"><span class="color-dot color-'+esc(p.color||'none')+'"></span><strong>'+esc(p.name)+'</strong><small>'+money(p.price)+' · Stock '+p.stock+'</small></button>').join('');const draft=draftProductId?productById(draftProductId):null;if(draft){$('productDraft').innerHTML='<div class="draft-product"><div class="draft-info"><span class="color-dot color-'+esc(draft.color||'none')+'"></span><div><strong>'+esc(draft.name)+'</strong><small>Stock '+draft.stock+' · '+money(draft.price)+'</small></div></div><div class="draft-controls"><input id="draftQty" type="number" min="1" max="'+Math.max(0,draft.stock)+'" step="1" inputmode="numeric" value="'+esc(draftQty)+'" placeholder="Cantidad"><button id="assignDraft" class="primary" type="button" '+(!draftQty||Number(draftQty)<1?'disabled':'')+'>Asignar</button></div></div>'}else $('productDraft').innerHTML='';const chosen=cart.map(i=>{const p=productById(i.productId);if(!p)return '';const ep=effectivePrice(p,i.qty);return '<div class="chosen-line"><div><strong>'+esc(p.name)+'</strong><span>'+i.qty+' × '+money(ep.price)+(ep.applied?' · OFERTA':'')+'</span></div><div class="chosen-actions"><button class="qty-btn chosen-minus" data-id="'+esc(p.id)+'" type="button">−</button><b>'+i.qty+'</b><button class="qty-btn chosen-plus" data-id="'+esc(p.id)+'" type="button">＋</button><button class="delete-line" data-id="'+esc(p.id)+'" type="button" aria-label="Eliminar producto">✕</button></div></div>'}).join('');$('chosenProducts').innerHTML=chosen||'<p class="muted">La bandeja está vacía.</p>';$('chosenProducts').classList.toggle('hidden',!showCartTray);$('toggleCartTray').textContent=showCartTray?'Ocultar bandeja':'Ver bandeja ('+cart.reduce((a,i)=>a+Number(i.qty||0),0)+')';$('cartItems').innerHTML='';document.querySelectorAll('.cart-plus,.chosen-plus').forEach(btn=>btn.onclick=()=>changeCart(btn.dataset.id,1));document.querySelectorAll('.cart-minus,.chosen-minus').forEach(btn=>btn.onclick=()=>changeCart(btn.dataset.id,-1));document.querySelectorAll('.delete-line').forEach(btn=>btn.onclick=()=>{cart=cart.filter(i=>String(i.productId)!==String(btn.dataset.id));renderCart()});document.querySelectorAll('.suggestion').forEach(btn=>btn.onclick=()=>{if(!draftProductId||!draftQty){draftProductId=btn.dataset.id;draftQty='';renderCart();setTimeout(()=>{const q=$('draftQty');if(q){q.focus();q.select()}},0)}});if($('draftQty'))$('draftQty').oninput=e=>{draftQty=e.target.value.replace(/\\D/g,'');renderCart();setTimeout(()=>{const q=$('draftQty');if(q){q.focus();q.setSelectionRange(q.value.length,q.value.length)}},0)};if($('assignDraft'))$('assignDraft').onclick=()=>{const qty=Math.floor(Number(draftQty)||0);if(!draft||qty<1)return;const existing=cart.find(i=>String(i.productId)===String(draft.id));const stockKey=draft.baseProductId||draft.id;const used=cart.reduce((a,x)=>{const p=productById(x.productId);return a+(p&&(p.baseProductId||p.id)===stockKey?Number(x.qty||0):0)},0);const current=existing?Number(existing.qty||0):0;if(qty+used-current>draft.stock){return}if(existing)existing.qty+=qty;else cart.push({productId:draft.id,qty});draftProductId='';draftQty='';$('saleStatus').textContent='';renderCart();$('cartSearchName').focus()};let total=0;cart.forEach(i=>{const p=productById(i.productId);if(p)total+=effectivePrice(p,i.qty).price*i.qty});$('cartTotal').textContent=money(total)}function changeCart(id,delta){const p=productById(id);if(!p)return;let i=cart.find(x=>String(x.productId)===String(id));const next=(i?i.qty:0)+delta;const stockKey=p.baseProductId||p.id;const used=cart.reduce((a,x)=>{const q=productById(x.productId);return a+(q&&(q.baseProductId||q.id)===stockKey?Number(x.qty||0):0)},0);if(next<=0){cart=cart.filter(x=>String(x.productId)!==String(id))}else if(next<=p.stock-used){if(i)i.qty=next;else cart.push({productId:p.id,qty:next})}else{return}$('saleStatus').textContent='';renderCart()}
function showPromos(id){const p=productById(id);if(!p)return;const lines=(p.promotions||[]).map(x=>'Desde '+x.minQty+' unidades → '+money(x.price)).join('\n');alert((p.name||'Producto')+'\n\n'+(lines||'No hay promociones programadas.')+'\n\nLa promoción se aplica automáticamente al alcanzar la cantidad.')}
function cartData(){const items=cart.map(i=>{const p=productById(i.productId);if(!p)return null;const ep=effectivePrice(p,i.qty);return{productId:p.id,baseProductId:p.baseProductId||p.id,desc:p.name,flavor:p.flavor||'',qty:i.qty,price:ep.price,purchasePrice:p.pricePurchase,promotion:ep.applied||null}}).filter(Boolean);return{items,total:items.reduce((a,i)=>a+i.qty*i.price,0),cost:items.reduce((a,i)=>a+i.qty*i.purchasePrice,0)}}
function openSaveOptions(){if(!cartData().items.length){$('saleStatus').textContent='Agrega productos al carrito.';return}$('saveOptions').classList.remove('hidden')}
function closeSaveOptions(){$('saveOptions').classList.add('hidden')}
function finalizeSale(printAfter){const c=clientById(selectedClientId);if(!c)return;const d=cartData();if(!d.items.length){closeSaveOptions();return}const ps=getRawProducts();d.items.forEach(i=>{const baseId=i.baseProductId||i.productId;const p=ps.find(x=>String(x.id)===String(baseId));if(p)p.stock=Math.max(0,Number(p.stock||0)-i.qty)});if(!writeArray('zipperProductos',ps)){closeSaveOptions();return}const sales=getSales();const folio=Math.max(0,...sales.map(s=>Number(s.folio)||0))+1;const sale={id:uid(),folio,fecha:localDate(),clienteId:c.id,cliente:c.name,ruta:c.route||'',routeWeek:c.routeWeek||'',routeDay:c.routeDay||'',items:d.items,total:d.total,cost:d.cost,profit:d.total-d.cost};sales.push(sale);if(writeArray('zipperComprobantes',sales)){markVisited(c.id);closeSaveOptions();cart=[];draftProductId='';draftQty='';showCartTray=false;renderInventory();$('saleStatus').textContent=(printAfter?'Venta guardada e impresión enviada. ':'Venta guardada correctamente. ')+'Folio #'+folio;renderPrint(sale);if(printAfter)window.print();selectedClientId='';$('cartSection').classList.add('hidden');renderHome();}}
function saveSale(){openSaveOptions()}
function printSale(){openSaveOptions()}
function renderCash(){const today=getSales().filter(s=>saleDate(s)===localDate());const sales=today.reduce((a,s)=>a+saleTotal(s),0),cost=today.reduce((a,s)=>a+saleCost(s),0);$('cashSales').textContent=money(sales);$('cashCost').textContent=money(cost);$('cashProfit').textContent=money(sales-cost);renderStats();renderGeneralTotal()}
function renderStats(){const rows=getSales().filter(s=>periodMatch(saleDate(s),statPeriod));const out={};if(statType==='day'){const total=rows.reduce((a,s)=>a+saleTotal(s),0),cost=rows.reduce((a,s)=>a+saleCost(s),0);$('statsOutput').innerHTML='<div class="stat-line"><div><strong>Ventas</strong><small>'+rows.length+' comprobantes</small></div><strong>'+money(total)+'</strong></div><div class="stat-line"><div><strong>Invertido</strong></div><strong>'+money(cost)+'</strong></div><div class="stat-line"><div><strong>Ganado</strong></div><strong>'+money(total-cost)+'</strong></div>';return}if(statType==='client'){rows.forEach(s=>{const k=s.cliente||'Sin cliente';if(!out[k])out[k]={qty:0,total:0,cost:0};out[k].qty++;out[k].total+=saleTotal(s);out[k].cost+=saleCost(s)})}else if(statType==='route'){rows.forEach(s=>{const k=s.ruta||'Sin ruta';if(!out[k])out[k]={qty:0,total:0,cost:0};out[k].qty++;out[k].total+=saleTotal(s);out[k].cost+=saleCost(s)})}else{rows.forEach(s=>(s.items||[]).forEach(i=>{const k=i.desc||'Producto';if(!out[k])out[k]={qty:0,total:0,cost:0};out[k].qty+=Number(i.qty||0);out[k].total+=Number(i.qty||0)*Number(i.price||0);out[k].cost+=Number(i.qty||0)*Number(i.purchasePrice||0)}))}const arr=Object.entries(out).map(([k,v])=>({...v,name:k,profit:v.total-v.cost})).sort((a,b)=>statType==='product'?b.qty-a.qty:b.total-a.total);$('statsOutput').innerHTML=arr.length?arr.map(v=>'<div class="stat-line"><div><strong>'+esc(v.name)+'</strong><small>'+v.qty+(statType==='product'?' unidades':' ventas')+' · Ganancia '+money(v.profit)+'</small></div><strong>'+money(v.total)+'</strong></div>').join(''):'<p class="muted">No hay datos en este período.</p>'}
function renderGeneralTotal(){const rows=getSales().filter(s=>periodMatch(saleDate(s),totalPeriod)),t=rows.reduce((a,s)=>a+saleTotal(s),0);$('generalTotal').textContent=money(t);$('generalTotalMeta').textContent=rows.length+' ventas registradas en el período.'}

function resetProductForm(){editingProductId=null;photoData='';currentPromos=[];$('productFormTitle').textContent='Ingreso de producto nuevo';$('productStockLabel').textContent='Stock inicial';$('productStockHelp').textContent='Cantidad disponible al ingresar el producto.';$('productName').value='';$('productBuy').value='';$('productSell').value='';$('productStock').value='';$('productPhoto').value='';$('productStatus').textContent='';$('cancelProduct').classList.add('hidden');renderProductPhoto();renderPromoRows()}
function renderProductForm(){renderCategoriesOptions();$('productStockLabel').textContent=editingProductId?'Agregar unidades al stock':'Stock inicial';$('productStockHelp').textContent=editingProductId?'Stock actual: '+(getRawProducts().find(x=>String(x.id)===String(editingProductId))?.stock??0)+'. Las unidades ingresadas se sumarán automáticamente.':'Cantidad disponible al ingresar el producto.';}
function renderCategoriesOptions(){const cats=getCategories();$('productCategory').innerHTML=cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('')}
function renderProductPhoto(){$('productPhotoPreview').innerHTML=photoData?'<img src="'+photoData+'" alt="Foto del producto">':'Foto'}
function renderPromoRows(){$('promoRows').innerHTML=currentPromos.map((p,i)=>'<div class="promo-row"><input aria-label="Cantidad" type="number" min="1" step="1" value="'+esc(p.minQty)+'" data-promo-min="'+i+'" placeholder="Cantidad"><input aria-label="Precio oferta" type="number" min="0" step="1" value="'+esc(p.price)+'" data-promo-price="'+i+'" placeholder="Precio oferta"><span class="promo-tag">OFERTA</span><button data-promo-del="'+i+'" type="button">Eliminar</button></div>').join('');document.querySelectorAll('[data-promo-min]').forEach(e=>e.oninput=()=>currentPromos[Number(e.dataset.promoMin)].minQty=Number(e.value));document.querySelectorAll('[data-promo-price]').forEach(e=>e.oninput=()=>currentPromos[Number(e.dataset.promoPrice)].price=Number(e.value));document.querySelectorAll('[data-promo-del]').forEach(e=>e.onclick=()=>{currentPromos.splice(Number(e.dataset.promoDel),1);renderPromoRows()})}
function saveProduct(){const name=$('productName').value.trim(),buy=Number($('productBuy').value),sell=Number($('productSell').value),enteredStock=Math.max(0,Number($('productStock').value)||0),category=$('productCategory').value;if(!name||!Number.isFinite(buy)||buy<0||!Number.isFinite(sell)||sell<0||!category){$('productStatus').textContent='Completa nombre, compra, venta y categoría.';return}const ps=getRawProducts();const clean=currentPromos.filter(p=>Number(p.minQty)>0&&Number.isFinite(Number(p.price))).map(p=>({minQty:Number(p.minQty),price:Number(p.price),label:'Desde '+p.minQty+' unidades: '+money(p.price)}));if(editingProductId){const p=ps.find(x=>String(x.id)===String(editingProductId));if(p){Object.assign(p,{name,pricePurchase:buy,price:sell,stock:Number(p.stock||0)+enteredStock,category,image:photoData||p.image||'',promotions:clean})}}else ps.push({id:uid(),name,pricePurchase:buy,price:sell,stock:enteredStock,category,active:true,image:photoData,promotions:clean});if(writeArray('zipperProductos',ps)){resetProductForm();renderInventory();$('productStatus').textContent='Producto guardado.'}}
function editProduct(id){const p=productById(id);if(!p)return;const rawId=p.baseProductId||p.id;const raw=getRawProducts().find(x=>String(x.id)===String(rawId));if(!raw)return;editingProductId=raw.id;photoData=raw.image||'';currentPromos=(raw.promotions||[]).map(x=>({...x}));$('productFormTitle').textContent='Editar producto';$('productName').value=raw.name;$('productBuy').value=raw.pricePurchase;$('productSell').value=raw.price;$('productStock').value='';renderCategoriesOptions();$('productStockLabel').textContent='Agregar unidades al stock';$('productStockHelp').textContent='Stock actual: '+Number(raw.stock||0)+'. Las unidades que ingreses aquí se sumarán automáticamente.';$('productCategory').value=raw.category;renderProductPhoto();renderPromoRows();$('cancelProduct').classList.remove('hidden');window.scrollTo(0,0)}
function renderInventory(){const q=norm($('productSearch').value);const ps=getProducts().filter(p=>!q||norm(p.name).includes(q));$('inventoryList').innerHTML=ps.length?ps.map(p=>{const cls=p.stock<=0?'stock-zero':p.stock<=5?'stock-low':'stock-ok';return'<article class="inventory-row">'+(p.image?'<img class="product-list-image" src="'+esc(p.image)+'" alt="">':'')+'<div class="inventory-main"><strong>'+esc(p.name)+'</strong><span>'+esc(p.category)+' · Venta '+money(p.price)+' · Compra '+money(p.pricePurchase)+'</span><span>Promociones: '+((p.promotions||[]).length?'Sí':'No')+'</span></div><span class="stock-badge '+cls+'">'+(p.stock<=0?'SIN STOCK':p.stock<=5?'POCO STOCK':'STOCK '+p.stock)+'</span><div class="inventory-actions"><button class="secondary edit-product" data-id="'+esc(p.id)+'" type="button">Editar</button><button class="secondary adjust-stock" data-id="'+esc(p.id)+'" type="button">Stock</button></div></article>'}).join(''):'<p class="muted">No hay productos.</p>';document.querySelectorAll('.edit-product').forEach(b=>b.onclick=()=>editProduct(b.dataset.id));document.querySelectorAll('.adjust-stock').forEach(b=>b.onclick=()=>adjustStock(b.dataset.id))}
function adjustStock(id){const p=productById(id);if(!p)return;const rawId=p.baseProductId||p.id;const v=prompt('Nuevo stock para '+p.name,p.stock);if(v===null)return;const n=Number(v);if(!Number.isFinite(n)||n<0)return;const ps=getRawProducts();const x=ps.find(z=>String(z.id)===String(rawId));if(!x)return;x.stock=Math.floor(n);writeArray('zipperProductos',ps);renderInventory()}
function renderCategories(){renderCategoriesOptions();$('categoryList').innerHTML=getCategories().map(c=>'<span class="chip">'+esc(c)+'</span>').join('')}

function resetClientForm(){editingClientId=null;$('clientFormTitle').textContent='Nuevo cliente';$('clientName').value='';$('clientRut').value='';$('clientPhone').value='';$('clientAddress').value='';$('clientWeek').value='A';$('clientDay').value='';$('clientValidation').textContent='';$('clientValidation').className='validation';$('cancelClient').classList.add('hidden')}
function formatRut(r){const s=String(r||'').toUpperCase().replace(/[^0-9K]/g,'');if(s.length<2)return s;return s.slice(0,-1).replace(/\B(?=(\d{3})+(?!\d))/g,'.')+'-'+s.slice(-1)}
function formatPhone(v){const s=String(v||'').replace(/\D/g,'').replace(/^569/,'').slice(0,8);return s?'569 '+s.slice(0,4)+(s.length>4?' '+s.slice(4):''):''}
function validateRut(r){const s=String(r||'').toUpperCase().replace(/[^0-9K]/g,'');if(!s||s.length<2)return false;const body=s.slice(0,-1),dv=s.slice(-1);let sum=0,m=2;for(let i=body.length-1;i>=0;i--){sum+=Number(body[i])*m;m=m===7?2:m+1}const d=11-(sum%11),want=d===11?'0':d===10?'K':String(d);return want===dv}
function validateClientField(show=true){const rut=$('clientRut').value.trim(),phone=$('clientPhone').value.replace(/\D/g,'');let msg='';if(rut&&!validateRut(rut))msg='RUT mal ingresado.';else if(phone&&(phone.replace(/^569/,'').length!==8))msg='Teléfono mal ingresado. Debe ser 569 + 8 dígitos.';if(show){$('clientValidation').textContent=msg;$('clientValidation').className='validation'+(msg?'':' ok')}return !msg}
function bindImmediateValidation(id){$(id).addEventListener('blur',()=>{if(id==='clientRut')$(id).value=formatRut($(id).value);if(id==='clientPhone')$(id).value=formatPhone($(id).value);validateClientField(true)});$(id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(id==='clientRut')$(id).value=formatRut($(id).value);if(id==='clientPhone')$(id).value=formatPhone($(id).value);validateClientField(true);$(id).blur()}})}
function saveClient(){if(!validateClientField(true))return;const name=$('clientName').value.trim(),address=$('clientAddress').value.trim();if(!name||!address){$('clientValidation').textContent='Nombre y dirección son obligatorios.';return}const rut=$('clientRut').value.trim().toUpperCase(),cs=getClients();if(rut&&cs.some(c=>c.rut===rut&&String(c.id)!==String(editingClientId))){$('clientValidation').textContent='Ese RUT ya está registrado.';return}const data={name,rut,phone:$('clientPhone').value.replace(/\D/g,''),address,route:'',routeWeek:$('clientWeek').value,routeDay:$('clientDay').value,active:true};if(editingClientId){const c=cs.find(x=>String(x.id)===String(editingClientId));if(c)Object.assign(c,data)}else cs.push({id:uid(),...data});if(writeArray('zipperClientes',cs)){resetClientForm();renderClients();renderHome()}}
function editClient(id){const c=clientById(id);if(!c)return;editingClientId=c.id;$('clientFormTitle').textContent='Editar cliente';$('clientName').value=c.name;$('clientRut').value=c.rut;$('clientPhone').value=formatPhone(c.phone);$('clientAddress').value=c.address;$('clientWeek').value=c.routeWeek||'1';$('clientDay').value=c.routeDay||'';$('cancelClient').classList.remove('hidden');validateClientField(false);window.scrollTo(0,0)}
function renderClients(){const all=getClients();const qn=norm($('clientSearchName').value),q=norm($('clientSearchAddress').value),w=$('filterWeek').value,d=$('filterDay').value;let rows=all.filter(c=>c.active!==false&&(!qn||norm(c.name).includes(qn))&&(!q||norm(c.address).includes(q))&&(!w||String(c.routeWeek)===String(w))&&(!d||norm(c.routeDay)===norm(d)));rows.sort((a,b)=>a.name.localeCompare(b.name,'es'));$('clientList').innerHTML=rows.length?rows.map(c=>'<article class="client-row"><div><strong>'+esc(c.name)+'</strong><span>'+esc(c.address)+'</span><span>Tel: '+esc(c.phone||'Sin teléfono')+' · RUT: '+esc(c.rut||'Sin RUT')+'</span><span>'+esc(c.route||'Sin ruta')+' · Semana '+esc(c.routeWeek||'—')+' · '+esc(c.routeDay||'Sin día')+'</span></div><div class="actions-small"><button class="secondary edit-client" data-id="'+esc(c.id)+'" type="button">Editar</button><button class="primary client-sale" data-id="'+esc(c.id)+'" type="button">Vender</button></div></article>').join(''):'<p class="muted">No hay clientes para esta selección.</p>';document.querySelectorAll('.edit-client').forEach(b=>b.onclick=()=>editClient(b.dataset.id));document.querySelectorAll('.client-sale').forEach(b=>b.onclick=()=>{showView('home');openClientCart(b.dataset.id)})}

function renderHistory(){const from=$('historyFrom').value,to=$('historyTo').value;if(historyType==='sales'){const rows=getSales().filter(s=>(!from||saleDate(s)>=from)&&(!to||saleDate(s)<=to)).sort((a,b)=>saleDate(b).localeCompare(saleDate(a)));$('historyOutput').innerHTML=rows.length?rows.map(s=>'<article class="history-row"><div><strong>#'+esc(s.folio)+' · '+esc(s.cliente)+'</strong><span>'+esc(s.fecha)+' · '+esc(s.ruta||'Sin ruta')+' · '+(s.items||[]).length+' líneas</span></div><div class="actions-small"><strong>'+money(saleTotal(s))+'</strong><button class="secondary print-history" data-id="'+esc(s.id)+'" type="button">Imprimir</button></div></article>').join(''):'<p class="muted">No hay ventas en este período.</p>'}else if(historyType==='clients'){const sums={};getSales().forEach(s=>{if((!from||saleDate(s)>=from)&&(!to||saleDate(s)<=to)){const k=s.cliente||'Sin cliente';sums[k]=(sums[k]||0)+saleTotal(s)}});const rows=Object.entries(sums).sort((a,b)=>b[1]-a[1]);$('historyOutput').innerHTML=rows.length?rows.map(x=>'<article class="history-row"><div><strong>'+esc(x[0])+'</strong><span>Total acumulado del período</span></div><strong>'+money(x[1])+'</strong></article>').join(''):'<p class="muted">No hay movimientos.</p>'}else{const sums={};getSales().forEach(s=>{if((!from||saleDate(s)>=from)&&(!to||saleDate(s)<=to))(s.items||[]).forEach(i=>{const k=i.desc||'Producto';if(!sums[k])sums[k]={qty:0,total:0,profit:0};sums[k].qty+=Number(i.qty||0);sums[k].total+=Number(i.qty||0)*Number(i.price||0);sums[k].profit+=Number(i.qty||0)*(Number(i.price||0)-Number(i.purchasePrice||0))})});const rows=Object.entries(sums).sort((a,b)=>b[1].qty-a[1].qty);$('historyOutput').innerHTML=rows.length?rows.map(x=>'<article class="history-row"><div><strong>'+esc(x[0])+'</strong><span>'+x[1].qty+' unidades · Ganancia '+money(x[1].profit)+'</span></div><strong>'+money(x[1].total)+'</strong></article>').join(''):'<p class="muted">No hay movimientos de productos.</p>'}document.querySelectorAll('.print-history').forEach(b=>b.onclick=()=>{const s=getSales().find(x=>String(x.id)===String(b.dataset.id));if(s){renderPrint(s);window.print()}})}

function renderPrint(s){$('printArea').innerHTML='<div class="receipt"><h2>DISTRIBUIDORA ZIPPER</h2><div>Comprobante #'+esc(s.folio)+' · '+esc(s.fecha)+'</div><div style="margin:6px 0"><strong>'+esc(s.cliente)+'</strong></div>'+(s.items||[]).map(i=>'<div class="line"><span>'+esc(i.qty)+' × '+esc(i.desc)+(i.promotion?' · OFERTA':'')+'</span><strong>'+money(Number(i.qty)*Number(i.price))+'</strong></div>').join('')+'<div class="total"><span>TOTAL</span><strong>'+money(saleTotal(s))+'</strong></div></div>'}
function addCategory(){const n=$('newCategory').value.trim();if(!n)return;const cs=getCategories();if(cs.some(x=>norm(x)===norm(n))){$('categoryStatus').textContent='Esa categoría ya existe.';return}const saved=readArray('zipperCategorias').filter(x=>String(x).trim());const removed=readArray('zipperCategoriasEliminadas').filter(x=>norm(x)!==norm(n));saved.push(n);writeArray('zipperCategorias',saved);writeArray('zipperCategoriasEliminadas',removed);$('newCategory').value='';$('categoryStatus').textContent='Categoría creada.';renderCategories()}
function renameCategory(oldName,next){if(!next||norm(next)===norm(oldName))return;const cs=getCategories();if(cs.some(x=>norm(x)===norm(next))){alert('Ya existe una categoría con ese nombre.');return}const saved=readArray('zipperCategorias').filter(x=>String(x).trim());const removed=readArray('zipperCategoriasEliminadas').filter(x=>norm(x)!==norm(next));const si=saved.findIndex(x=>norm(x)===norm(oldName));if(si>=0)saved[si]=next;else saved.push(next);if(!removed.some(x=>norm(x)===norm(oldName)))removed.push(oldName);const ps=getRawProducts();ps.forEach(p=>{if(norm(p.category)===norm(oldName))p.category=next});writeArray('zipperCategorias',saved);writeArray('zipperCategoriasEliminadas',removed);writeArray('zipperProductos',ps);renderCategories();renderInventory();renderCategoriesOptions();$('categoryStatus').textContent='Categoría modificada.'}
function editCategory(oldName){const n=prompt('Nuevo nombre para la categoría:',oldName);if(n!==null)renameCategory(oldName,n.trim())}
function deleteCategory(name){if(norm(name)==='otros'){alert('La categoría Otros no se puede eliminar porque funciona como respaldo.');return}const used=getRawProducts().some(p=>norm(p.category)===norm(name));if(!confirm('¿Eliminar la categoría "'+name+'"?'+(used?' Los productos que la usan pasarán a "Otros".':'')))return;const saved=readArray('zipperCategorias').filter(x=>norm(x)!==norm(name));const removed=readArray('zipperCategoriasEliminadas').filter(x=>norm(x)!==norm(name));removed.push(name);const ps=getRawProducts();ps.forEach(p=>{if(norm(p.category)===norm(name))p.category='Otros'});writeArray('zipperCategorias',saved);writeArray('zipperCategoriasEliminadas',removed);writeArray('zipperProductos',ps);renderCategories();renderInventory();renderCategoriesOptions();$('categoryStatus').textContent='Categoría eliminada.'}
function renderCategories(){renderCategoriesOptions();const cs=getCategories();$('categoryList').innerHTML=cs.length?cs.map(c=>'<div class="category-admin-row"><input value="'+esc(c)+'" data-category-input="'+esc(c)+'"><div class="category-admin-actions"><button class="secondary edit-category" data-category="'+esc(c)+'" type="button">Modificar</button><button class="secondary delete-category" data-category="'+esc(c)+'" type="button">Eliminar</button></div></div>').join(''):'<p class="muted">No hay categorías.</p>';document.querySelectorAll('.edit-category').forEach(b=>b.onclick=()=>{const n=document.querySelector('[data-category-input="'+CSS.escape(b.dataset.category)+'"]')?.value.trim();renameCategory(b.dataset.category,n||b.dataset.category)});document.querySelectorAll('.delete-category').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.category))}

